from collections import deque
def comps(g,val):
    seen=set(); res=[]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v==val and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]==val and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                res.append(cells)
    return res
