def move_toward(cellsA,cellsB):
    # return next cell for A: reduce Chebyshev distance to B center, prefer axes
    ca=collections.defaultdict(list)
    for r_,c_ in cellsA: ca[r_].append(c_)
    ra=[r_ for r_ in ca]
    cb=collections.defaultdict(list)
    for r_,c_ in cellsB: cb[r_].append(c_)
