def comps_all(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen or g[r][c]==0: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                a,b=stack.pop(); cells.append((a,b))
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]!=0:
                            seen.add((x,y)); stack.append((x,y))
            out.append(cells)
    return out
